#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(transparent)]
pub struct CapsuleFlags(pub asnkitrt::serde_value::BitString);

impl CapsuleFlags {
    pub const COMMIT_TO_FUSES: usize = 0;
    pub const KEY_SET: usize = 1;
    pub const PATCH: usize = 2;
    pub const COMPRESSED: usize = 3;
    /// The bits that have names.
    pub const NAMED: &'static [usize] = &[0, 1, 2, 3];

    /// No bit set.
    pub fn empty() -> Self {
        CapsuleFlags(asnkitrt::serde_value::BitString {
            data: Vec::new(),
            bits: 0,
        })
    }

    /// The bit `bit`.
    pub fn get(&self, bit: usize) -> bool {
        self.0.bit(bit)
    }

    /// Sets the bit `bit` to `value`, without the zero bits at the end.
    pub fn set(&mut self, bit: usize, value: bool) {
        self.0.set_bit(bit, value);
        self.0.trim();
    }

    /// If a bit is set that has no name.
    pub fn has_unknown_bits(&self) -> bool {
        self.0.has_bits_other_than(Self::NAMED)
    }

    pub fn commit_to_fuses(&self) -> bool {
        self.get(Self::COMMIT_TO_FUSES)
    }

    pub fn key_set(&self) -> bool {
        self.get(Self::KEY_SET)
    }

    pub fn patch(&self) -> bool {
        self.get(Self::PATCH)
    }

    pub fn compressed(&self) -> bool {
        self.get(Self::COMPRESSED)
    }

    pub fn set_commit_to_fuses(&mut self, value: bool) {
        self.set(Self::COMMIT_TO_FUSES, value);
    }

    pub fn set_key_set(&mut self, value: bool) {
        self.set(Self::KEY_SET, value);
    }

    pub fn set_patch(&mut self, value: bool) {
        self.set(Self::PATCH, value);
    }

    pub fn set_compressed(&mut self, value: bool) {
        self.set(Self::COMPRESSED, value);
    }
}

impl Asn1Type for CapsuleFlags {
    const MODULE: &'static str = "OTPS-Capsule-V1";
    const NAME: &'static str = "CapsuleFlags";
}

